from __future__ import annotations

import os
from packaging.version import Version


def find_only_one_key(lmp_lines, key):
    found = []
    for idx in range(len(lmp_lines)):
        words = lmp_lines[idx].split()
        nkey = len(key)
        if len(words) >= nkey and words[:nkey] == key:
            found.append(idx)
    if len(found) > 1:
        raise RuntimeError("found %d keywords %s" % (len(found), key))  # noqa: UP031
    if len(found) == 0:
        raise RuntimeError(f"failed to find keyword {key}")
    return found[0]


def revise_lmp_input_model(
    lmp_lines,
    task_model_list,
    trj_freq,
    deepmd_version="1",
    use_ele_temp=0,
    workflow_options=None,
    ele_temp_f=None,
    ele_temp_a=None,
):
    if workflow_options is None:
        workflow_options = {}
    idx = find_only_one_key(lmp_lines, ["pair_style", "deepmd"])
    graph_list = " ".join(task_model_list)
    if Version(deepmd_version) < Version("1"):
        lmp_lines[idx] = "pair_style      deepmd %s %d model_devi.out\n" % (  # noqa: UP031
            graph_list,
            trj_freq,
        )
    else:
        keywords = ""
        if workflow_options.get("use_clusters", False):
            keywords += "atomic "
        if workflow_options.get("use_relative", False):
            keywords += "relative {} ".format(workflow_options["epsilon"])
        if workflow_options.get("use_relative_v", False):
            keywords += "relative_v {} ".format(workflow_options["epsilon_v"])
        if ele_temp_f is not None:
            keywords += "fparam ${ELE_TEMP}"
        elif ele_temp_a is not None:
            keywords += "aparam ${ELE_TEMP}"
        elif use_ele_temp == 1:
            keywords += "fparam ${ELE_TEMP}"
        elif use_ele_temp == 2:
            keywords += "aparam ${ELE_TEMP}"
        lmp_lines[idx] = (
            "pair_style      deepmd %s out_freq %d out_file model_devi.out %s\n"  # noqa: UP031
            % (
                graph_list,
                trj_freq,
                keywords,
            )
        )
    return lmp_lines


def build_template_options(settings, use_ele_temp=0):
    template_options = dict(settings.get("template_options", {}))
    template_options.update(
        {
            "deepmd_version": settings.get("deepmd_version", "1"),
            "use_ele_temp": use_ele_temp,
            "workflow_options": settings.get("workflow_options", {}),
        }
    )
    if settings.get("ele_temp_f") is not None:
        template_options["use_ele_temp"] = 1
        template_options["ele_temp_f"] = settings["ele_temp_f"]
    elif settings.get("ele_temp_a") is not None:
        template_options["use_ele_temp"] = 2
        template_options["ele_temp_a"] = settings["ele_temp_a"]
    return template_options


def render_external_template_input(template_lines, task_model_list, trj_freq, template_options):
    revised_lines = list(template_lines)
    revised_lines = revise_lmp_input_model(
        revised_lines, task_model_list, trj_freq, **template_options
    )
    workflow_options = template_options.get("workflow_options", {})
    if not isinstance(workflow_options, dict):
        workflow_options = {}
    model_devi_merge_traj = bool(workflow_options.get("model_devi_merge_traj", False))
    revised_lines = revise_lmp_input_dump(
        revised_lines, trj_freq, model_devi_merge_traj
    )
    return revised_lines


def revise_lmp_input_dump(lmp_lines, trj_freq, model_devi_merge_traj=False):
    if not model_devi_merge_traj:
        return lmp_lines
    dump_idx = None
    for ii in range(len(lmp_lines)):
        words = lmp_lines[ii].split()
        if len(words) >= 2 and words[0] == "dump" and "lammpstrj" in lmp_lines[ii]:
            dump_idx = ii
            break
    if dump_idx is None:
        return lmp_lines
    dump_id = lmp_lines[dump_idx].split()[1]
    lmp_lines[dump_idx] = lmp_lines[dump_idx].replace("traj/*.lammpstrj", "all.lammpstrj")
    has_dump_modify = any(
        "dump_modify" in " ".join(line.split()) for line in lmp_lines
    )
    if not has_dump_modify:
        lmp_lines.insert(
            dump_idx + 1,
            'if "${restart} > 0" then "dump_modify     %s append yes"\n'  # noqa: UP031
            % dump_id,
        )
    return lmp_lines


def revise_lmp_input_plm(lmp_lines, in_plm, out_plm="output.plumed"):
    idx = find_only_one_key(lmp_lines, ["fix", "dpgen_plm"])
    lmp_lines[idx] = (
        f"fix            dpgen_plm all plumed plumedfile {in_plm} outfile {out_plm}\n"
    )
    return lmp_lines


def revise_by_keys(lmp_lines, keys, values):
    for kk, vv in zip(keys, values):
        for ii in range(len(lmp_lines)):
            words = lmp_lines[ii].split()
            if len(words) > 0 and words[0] == kk:
                lmp_lines[ii] = vv + "\n"
    return lmp_lines


